from cart import cart_total

PEN = {"name": "pen", "price": 1.50, "qty": 4}
BOOK = {"name": "book", "price": 12.99, "qty": 1}


def test_empty_cart():
    assert cart_total([], None) == 0.0


def test_pens():
    assert cart_total([PEN], None) == 6.0


def test_save10():
    assert cart_total([PEN, BOOK], "SAVE10") == 17.09


def test_code_is_case_sensitive():
    assert cart_total([BOOK], "save10") == 12.99

from dataclasses import dataclass


@dataclass
class Product:
