from models import Product
from receipt import print_receipt


def receipt_text(products, capsys):
    """The receipt, whether print_receipt returns it or prints it."""
    result = print_receipt(products)
    printed = capsys.readouterr().out
    return (result if isinstance(result, str) else printed).strip()


def test_empty(capsys):
    assert receipt_text([], capsys) == "TOTAL USD 0.00"


def test_one_product(capsys):
    assert receipt_text([Product("Pen", 150)], capsys) == "Pen USD 1.50\nTOTAL USD 1.50"


def test_two_products(capsys):
    products = [Product("Pen", 150), Product("Book", 1299)]
    assert receipt_text(products, capsys) == "Pen USD 1.50\nBook USD 12.99\nTOTAL USD 14.49"


def test_small_amount(capsys):
    assert receipt_text([Product("Gift card", 5)], capsys) == "Gift card USD 0.05\nTOTAL USD 0.05"

